//! Explicit Python wide-core fixture index. Payload discovery is intentionally not directory-based.

use crate::build_support::model::{WideFixture, WideKind};

macro_rules! fixture {
    ($family:literal, $name:literal, $kind:expr) => {
        fixture!($family, $name, $name, $kind)
    };
    ($family:literal, $name:literal, $stem:literal, $kind:expr) => {
        WideFixture {
            name: $name,
            source: include_str!(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/fixtures/python-wide/",
                $family,
                "/",
                $stem,
                ".tpz"
            )),
            source_path: concat!("fixtures/python-wide/", $family, "/", $stem, ".tpz"),
            kind: $kind,
        }
    };
}

